// Theme Handling
function setupTheme() {
    // Apply initial theme from saved settings
    applyTheme();

    // Setup settings modal
    const settingsTriggers = ['settings-btn', 'settings-btn-stack']
        .map((id) => document.getElementById(id))
        .filter(Boolean);
    const settingsModal = document.getElementById('settings-modal');
    const closeSettingsBtn = document.getElementById('close-settings-btn');
    const themeSelect = document.getElementById('theme-select');

    // Apply language immediately on startup.
    applySettingsLanguage();
    setupLanguagePicker();

    if (settingsTriggers.length && settingsModal) {
        settingsTriggers.forEach((settingsBtn) => {
            settingsBtn.addEventListener('click', () => {
            settingsModal.classList.remove('hidden');
            syncFooterZoomControl(getActiveUiZoomScale());
            resetSettingsEnforcementSection();
            void applyEnforcementDescCopy(lastMigrationBrowserState);
            // Re-evaluate the in-app Uninstall button (Mac only): a
            // schedule could have fired since the modal was last open,
            // flipping the disabled state. Cheap; idempotent.
            refreshUninstallButtonState();
            updateOverrideAllButtonVisibility();
            void wireEnforcementToggle();
            void wireBlockingMethodSettings();
            // Set current theme selection
            if (themeSelect) {
                const currentTheme = appData.settings?.themeMode || 'system';
                themeSelect.value = currentTheme;
            }
            void (async () => {
                applySettingsLanguage();

                // Fetch and display version info
                const currentVersionEl = document.getElementById('current-app-version');
                const latestVersionEl = document.getElementById('latest-app-version');
                const latestVersionWrap = document.getElementById('settings-latest-version-wrap');

                let currentVersion = null;

                if (currentVersionEl) {
                    try {
                        currentVersion = await tauriAPI.getAppVersion();
                        applyFormattedCurrentVersion(currentVersionEl, currentVersion || 'Unknown');
                    } catch (e) {
                        console.error('[Version] Error fetching current version:', e);
                        applyFormattedCurrentVersion(currentVersionEl, 'Unknown');
                    }
                }

                if (latestVersionEl) {
                    latestVersionEl.style.display = 'none';
                    if (latestVersionWrap) latestVersionWrap.style.display = 'none';

                    if (!(await resolveMicrosoftStorePackage())) {
                        try {
                            const response = await fetch(`https://ulyngs.github.io/redd-block/latest-versions.json?t=${Date.now()}`);
                            const versions = await response.json();
                            const latestVersion = versions[getLatestVersionPlatformKey()];

                            if (latestVersion && currentVersion && isVersionHigher(latestVersion, currentVersion)) {
                                applyFormattedLatestVersion(latestVersionEl, latestVersion);
                                latestVersionEl.style.display = 'block';
                                if (latestVersionWrap) latestVersionWrap.style.display = 'block';
                            }
                        } catch (e) {
                            console.log('[Version] Could not check for updates (offline or error):', e.message);
                        }
                    }
                }
            })();
            });
        });
    }

    if (closeSettingsBtn && settingsModal) {
        closeSettingsBtn.addEventListener('click', () => {
            setLanguagePickerOpen(false);
            settingsModal.classList.add('hidden');
            stopHelperUiRefreshLoop();
        });
    }

    // Close modal when clicking outside
    if (settingsModal) {
        settingsModal.addEventListener('click', (e) => {
            if (e.target === settingsModal) {
                setLanguagePickerOpen(false);
                settingsModal.classList.add('hidden');
                stopHelperUiRefreshLoop();
            }
        });
    }

    // Theme selection change
    if (themeSelect) {
        themeSelect.addEventListener('change', (e) => {
            if (!appData.settings) appData.settings = {};
            appData.settings.themeMode = e.target.value;

            // Update legacy darkMode for backwards compatibility
            if (e.target.value === 'dark') {
                appData.settings.darkMode = true;
            } else if (e.target.value === 'light') {
                appData.settings.darkMode = false;
            } else {
                // Auto/system mode - use system preference
                delete appData.settings.darkMode;
            }

            applyTheme();
            saveData();
        });
    }

    // Listen for system theme changes when in auto mode
    if (window.matchMedia) {
        window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
            if (appData.settings?.themeMode === 'system' || !appData.settings?.themeMode) {
                applyTheme();
            }
        });
    }
}

function applyTheme() {
    const body = document.body;
    const themeMode = appData.settings?.themeMode || 'system';

    let isDark;
    if (themeMode === 'dark') {
        isDark = true;
    } else if (themeMode === 'light') {
        isDark = false;
    } else {
        // Auto/system mode - detect system preference
        isDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
    }

    if (isDark) {
        body.classList.add('dark-mode');
    } else {
        body.classList.remove('dark-mode');
    }
}

function getUiZoomMax() {
    if (isIOS) return UI_ZOOM_MAX_IOS;
    const isDesktop = document.body.classList.contains('windows') || document.body.classList.contains('mac');
    return isDesktop ? UI_ZOOM_MAX_DESKTOP : UI_ZOOM_MAX;
}

function clampUiZoom(scale) {
    return Math.min(getUiZoomMax(), Math.max(UI_ZOOM_MIN, scale));
}

function getDefaultUiZoom() {
    return DEFAULT_UI_ZOOM;
}

function getSavedUiZoom() {
    const parsed = Number(appData.settings?.uiZoom);
    if (!Number.isFinite(parsed)) return getDefaultUiZoom();
    return clampUiZoom(parsed);
}

function isIosTablet() {
    return isIOS && !document.body.classList.contains('ios-phone');
}

/** Desktop only — iPad uses transform scaling; phones use CSS zoom. */
function usesNativeWebviewZoom() {
    if (!isIOS && (document.body.classList.contains('windows') || document.body.classList.contains('mac'))) {
        return nativeWebviewZoomSupported !== false;
    }
    return false;
}

function getActiveUiZoomScale() {
    const inline = parseFloat(document.documentElement.style.zoom);
    if (Number.isFinite(inline) && inline > 0) return inline;
    const cssVar = parseFloat(document.documentElement.style.getPropertyValue('--ui-zoom'));
    if (Number.isFinite(cssVar) && cssVar > 0) return cssVar;
    return getSavedUiZoom();
}

function getEffectiveViewportWidth() {
    const zoom = getActiveUiZoomScale();
    const viewportWidth = window.visualViewport?.width
        || window.innerWidth
        || document.documentElement?.clientWidth
        || 0;
    return viewportWidth > 0 ? viewportWidth / zoom : viewportWidth;
}

/** Mirror responsive layout tiers when UI zoom is above 100% (zoom ignores @media queries). iOS only. */
function syncUiZoomResponsiveLayout() {
    const zoom = getActiveUiZoomScale();
    document.documentElement.style.setProperty('--ui-zoom', String(zoom));

    if (isIOS) {
        const effVp = getEffectiveViewportWidth();
        const ipadPortraitStack = isIOS
            && usesStackSettingsPlacement()
            && !document.body.classList.contains('ios-phone');
        const cramped = effVp > UI_ZOOM_LAYOUT_STACK_MAX
            && effVp <= UI_ZOOM_LAYOUT_CRAMPED_MAX
            && !ipadPortraitStack;

        document.body.classList.toggle('ui-zoom-tier-stack', effVp > 0 && effVp <= UI_ZOOM_LAYOUT_STACK_MAX);
        document.body.classList.toggle('ui-zoom-tier-cramped', cramped);
        document.body.classList.toggle('ui-zoom-tier-narrow', effVp > 0 && effVp <= UI_ZOOM_LAYOUT_NARROW_MAX);
        document.body.classList.toggle('settings-placement-stack', usesStackSettingsPlacement());
    } else {
        document.body.classList.remove('settings-placement-stack');
        document.body.classList.remove(
            'ui-zoom-tier-stack',
            'ui-zoom-tier-cramped',
            'ui-zoom-tier-narrow',
        );
    }

    syncSchedulerModeTabLabelMode();
    syncIosScheduleDayLabelsViewportMode();
    syncAllStopBtnLabelFits();
    scheduleSelectionPromptLayout();
    const pauseModal = document.getElementById('pause-modal');
    if (pauseModal && !pauseModal.classList.contains('hidden')) {
        syncPauseDurationRowLayout();
    }
}

function usesStackSettingsPlacement() {
    if (window.matchMedia('(max-width: 768px)').matches) return true;
    return document.body.classList.contains('ios')
        && !document.body.classList.contains('ios-phone')
        && window.matchMedia('(min-width: 769px) and (max-width: 1024px) and (orientation: portrait)').matches;
}

/** True when labelled Now/Schedule tabs do not fit in the scheduler header row. */
function schedulerModeTabsNeedIconOnly(header, modeTabs, toolbar) {
    const toolbarVisible = toolbar && getComputedStyle(toolbar).display !== 'none';
    if (toolbarVisible) {
        const tabsRect = modeTabs.getBoundingClientRect();
        const toolbarRect = toolbar.getBoundingClientRect();
        if (tabsRect.right > toolbarRect.left - 6) {
            return true;
        }
    }
    if (header.scrollWidth > header.clientWidth + 1) {
        return true;
    }
    if (modeTabs.scrollWidth > modeTabs.clientWidth + 1) {
        return true;
    }
    for (const tab of modeTabs.querySelectorAll('.mode-tab')) {
        if (tab.scrollWidth > tab.clientWidth + 1) {
            return true;
        }
    }
    return false;
}

/** Keep desktop/iOS scheduler header chrome from overlapping as space tightens. */
function syncSchedulerModeTabLabelMode() {
    const enterHeader = document.getElementById('scheduler-enter-header');
    const timePicker = document.getElementById('time-picker-container');
    const modeTabs = enterHeader?.querySelector('.scheduler-mode-tabs');
    const body = document.body;
    if (!enterHeader || !modeTabs || !timePicker || timePicker.classList.contains('hidden')) {
        body.classList.remove('ui-zoom-sched-hide-title', 'ui-zoom-sched-tabs-icons');
        schedTabsIconOnlyEnteredAtWidth = 0;
        return;
    }

    const hadIconOnly = body.classList.contains('ui-zoom-sched-tabs-icons');
    const headerWidth = enterHeader.clientWidth;

    // If icon-only was the last stable state, only retry full labels after the
    // row actually gets wider. Otherwise the ResizeObserver can bounce forever
    // between the two near-identical layouts right at the threshold.
    if (hadIconOnly) {
        if (!schedTabsIconOnlyEnteredAtWidth) {
            schedTabsIconOnlyEnteredAtWidth = headerWidth;
            return;
        }
        if (headerWidth <= schedTabsIconOnlyEnteredAtWidth + SCHED_TABS_ICON_ONLY_EXIT_WIDTH_DELTA) {
            return;
        }
    }

    body.classList.remove('ui-zoom-sched-hide-title', 'ui-zoom-sched-tabs-icons');
    void enterHeader.offsetWidth;

    const mainTitle = document.getElementById('main-start-block-title');
    const toolbar = document.querySelector('#settings-toolbar-scheduler');
    const iconOnly = schedulerModeTabsNeedIconOnly(enterHeader, modeTabs, toolbar);

    if (!isIOS && mainTitle && iconOnly) {
        body.classList.add('ui-zoom-sched-hide-title');
        void enterHeader.offsetWidth;
    }

    body.classList.toggle('ui-zoom-sched-tabs-icons', iconOnly && isIOS);
    schedTabsIconOnlyEnteredAtWidth = iconOnly && isIOS ? enterHeader.clientWidth : 0;
}

function scheduleSelectionPromptLayout() {
    cancelAnimationFrame(selectionPromptLayoutRaf);
    selectionPromptLayoutRaf = requestAnimationFrame(() => {
        selectionPromptLayoutRaf = 0;
        syncSelectionPromptLayout();
    });
}

function isGridTopRowStacked() {
    const blocklists = document.getElementById('blocklists-section');
    const scheduler = document.getElementById('scheduler-section');
    if (!blocklists || !scheduler) return true;
    const blocklistsRect = blocklists.getBoundingClientRect();
    const schedulerRect = scheduler.getBoundingClientRect();
    return schedulerRect.top > blocklistsRect.top + 16;
}

function clearSelectionPromptLayout() {
    const prompt = document.getElementById('selection-prompt');
    const gridTopRow = document.querySelector('.grid-top-row');
    const schedulerSection = document.getElementById('scheduler-section');
    if (prompt) {
        prompt.style.top = '';
        prompt.style.left = '';
        prompt.style.right = '';
    }
    if (schedulerSection) {
        schedulerSection.style.removeProperty('--time-picker-placeholder-height');
    }
    if (gridTopRow) gridTopRow.classList.remove('grid-top-row--selection-prompt-active');
    document.body.classList.remove('selection-prompt-layout-two-col', 'selection-prompt-layout-stack');
}

function measureTimePickerPlaceholderHeight(section) {
    const mainContent = document.getElementById('main-content');
    const timePicker = section?.querySelector('#time-picker-container');
    if (!section || !mainContent || !timePicker || section.clientWidth <= 0) return 0;

    let measurer = document.getElementById('scheduler-placeholder-measurer');
    if (!measurer) {
        measurer = document.createElement('div');
        measurer.id = 'scheduler-placeholder-measurer';
        measurer.setAttribute('aria-hidden', 'true');
        measurer.style.cssText = 'position:absolute;left:-10000px;top:0;visibility:hidden;pointer-events:none;box-sizing:border-box;';
        mainContent.appendChild(measurer);
    }

    measurer.className = 'scheduler-content';
    measurer.style.width = `${section.clientWidth}px`;
    measurer.innerHTML = timePicker.outerHTML;

    const measuredPicker = measurer.querySelector('#time-picker-container');
    measuredPicker?.classList.remove('hidden');
    measuredPicker?.querySelector('#instant-block-panel')?.classList.remove('hidden');
    measuredPicker?.querySelector('#schedule-block-panel')?.classList.add('hidden');
    measuredPicker?.querySelector('.always-on-message')?.classList.add('hidden');
    measuredPicker?.querySelector('#timed-controls')?.classList.add('hidden');
    measuredPicker?.querySelector('#block-action-buttons')?.classList.add('hidden');

    return measuredPicker?.offsetHeight || 0;
}

/** Pin the empty-state hint to the first blocklist card (two-column) or reserve time-picker space (stack). */
function syncSelectionPromptLayout() {
    const prompt = document.getElementById('selection-prompt');
    const gridTopRow = document.querySelector('.grid-top-row');
    const schedulerSection = document.getElementById('scheduler-section');
    const firstCard = document.querySelector('#blocklists-container .blocklist-card');
    if (!prompt || !gridTopRow) return;

    const active = !prompt.classList.contains('hidden')
        && !gridTopRow.classList.contains('grid-top-row--blocklist-selected')
        && !!firstCard;

    if (!active) {
        clearSelectionPromptLayout();
        return;
    }

    const gap = 48;
    const stacked = isGridTopRowStacked();
    const anchorRect = gridTopRow.getBoundingClientRect();
    const cardRect = firstCard.getBoundingClientRect();
    const promptHeight = prompt.offsetHeight || 24;

    gridTopRow.classList.add('grid-top-row--selection-prompt-active');
    document.body.classList.toggle('selection-prompt-layout-two-col', !stacked);
    document.body.classList.toggle('selection-prompt-layout-stack', stacked);

    if (stacked) {
        prompt.style.top = '';
        prompt.style.left = '';
        prompt.style.right = '';
        if (schedulerSection) {
            const placeholderHeight = measureTimePickerPlaceholderHeight(schedulerSection);
            if (placeholderHeight > 0) {
                schedulerSection.style.setProperty('--time-picker-placeholder-height', `${placeholderHeight}px`);
            }
        }
        return;
    }

    if (schedulerSection) {
        schedulerSection.style.removeProperty('--time-picker-placeholder-height');
    }

    const top = cardRect.top - anchorRect.top + (cardRect.height - promptHeight) / 2;
    const left = cardRect.right - anchorRect.left + gap;
    prompt.style.top = `${Math.round(top)}px`;
    prompt.style.left = `${Math.round(left)}px`;
    prompt.style.right = '';
}

function scheduleUiZoomResponsiveLayout() {
    cancelAnimationFrame(uiZoomLayoutRaf);
    uiZoomLayoutRaf = requestAnimationFrame(() => {
        uiZoomLayoutRaf = 0;
        syncUiZoomResponsiveLayout();
    });
}

function bindUiZoomLayoutObserver() {
    if (uiZoomLayoutObserverBound || typeof ResizeObserver === 'undefined') return;
    const targets = [
        document.getElementById('main-content'),
        document.querySelector('.grid-top-row'),
        document.getElementById('scheduler-enter-header'),
        document.getElementById('scheduler-section'),
        document.getElementById('blocklists-container'),
        document.getElementById('selection-prompt'),
        document.querySelector('.week-calendar-section'),
        document.getElementById('day-rows'),
        document.querySelector('.footer'),
    ].filter(Boolean);
    if (!targets.length) return;
    uiZoomLayoutObserverBound = true;
    const ro = new ResizeObserver(() => {
        scheduleUiZoomResponsiveLayout();
        scheduleSelectionPromptLayout();
    });
    targets.forEach((el) => ro.observe(el));
}

function applyUiZoom(scale) {
    const clamped = clampUiZoom(scale);
    syncFooterZoomControl(clamped);
    document.documentElement.style.setProperty('--ui-zoom', String(clamped));

    if (usesNativeWebviewZoom()) {
        getCurrentWebview().setZoom(clamped).then(() => {
            nativeWebviewZoomSupported = true;
            document.documentElement.style.zoom = '';
            scheduleUiZoomResponsiveLayout();
        }).catch(() => {
            nativeWebviewZoomSupported = false;
            document.documentElement.style.zoom = String(clamped);
            scheduleUiZoomResponsiveLayout();
        });
        return;
    }

    // iPad WKWebView uses desktop content mode: neither CSS zoom nor pageZoom scales text.
    // `.app-container { transform: scale(var(--ui-zoom)) }` in styles.css handles iPad instead.
    if (isIosTablet()) {
        document.documentElement.style.zoom = '';
        scheduleUiZoomResponsiveLayout();
        return;
    }

    if (isIOS) {
        document.documentElement.style.zoom = String(clamped);
        scheduleUiZoomResponsiveLayout();
        return;
    }

    // Fallback when native webview zoom is unavailable (e.g. permission).
    document.documentElement.style.zoom = String(clamped);
    scheduleUiZoomResponsiveLayout();
}

/** Mirror the current zoom level into the settings control and +/- button state. */
function syncFooterZoomControl(scale) {
    const pct = `${Math.round(scale * 100)}%`;
    const max = getUiZoomMax();
    document.querySelectorAll('.zoom-value').forEach((el) => {
        el.textContent = pct;
    });
    document.querySelectorAll('.zoom-out-btn').forEach((btn) => {
        btn.disabled = scale <= UI_ZOOM_MIN + 1e-6;
    });
    document.querySelectorAll('.zoom-in-btn').forEach((btn) => {
        btn.disabled = scale >= max - 1e-6;
    });
}

function setupFooterZoomControl() {
    const control = document.getElementById('settings-zoom-control');
    if (!control || control.dataset.bound === '1') return;
    control.dataset.bound = '1';
    control.querySelector('.zoom-out-btn')?.addEventListener('click', () => zoomUiOut());
    control.querySelector('.zoom-in-btn')?.addEventListener('click', () => zoomUiIn());
}

function showUiZoomToast(scale) {
    const toast = document.getElementById('zoom-toast');
    const message = document.getElementById('zoom-toast-message');
    if (!toast || !message) return;

    message.textContent = `Zoom ${Math.round(scale * 100)}%`;
    toast.classList.remove('hidden');

    if (zoomToastHideTimeout) {
        clearTimeout(zoomToastHideTimeout);
    }
    zoomToastHideTimeout = setTimeout(() => {
        toast.classList.add('hidden');
        zoomToastHideTimeout = null;
    }, 1400);
}

function setUiZoom(scale, options = {}) {
    const clamped = clampUiZoom(scale);
    applyUiZoom(clamped);
    if (options.showToast) {
        showUiZoomToast(clamped);
    }

    if (!appData.settings) appData.settings = {};
    if (appData.settings.uiZoom === clamped) return;

    appData.settings.uiZoom = clamped;
    saveData();
}

function zoomUiIn(options = {}) {
    const current = getSavedUiZoom();
    setUiZoom(Math.round((current + UI_ZOOM_STEP) * 100) / 100, options);
}

function zoomUiOut(options = {}) {
    const current = getSavedUiZoom();
    setUiZoom(Math.round((current - UI_ZOOM_STEP) * 100) / 100, options);
}

function resetUiZoom(options = {}) {
    setUiZoom(getDefaultUiZoom(), options);
}

function setupUiZoomShortcuts() {
    setupFooterZoomControl();
    applyUiZoom(getSavedUiZoom());
    bindUiZoomLayoutObserver();
    window.addEventListener('resize', scheduleUiZoomResponsiveLayout, { passive: true });
    window.visualViewport?.addEventListener('resize', scheduleUiZoomResponsiveLayout, { passive: true });

    if (isIOS) return;

    tauriAPI.onMenuZoomIn(() => zoomUiIn({ showToast: true })).catch(() => { });
    tauriAPI.onMenuZoomOut(() => zoomUiOut({ showToast: true })).catch(() => { });
    tauriAPI.onMenuZoomReset(() => resetUiZoom({ showToast: true })).catch(() => { });

    document.addEventListener('keydown', (e) => {
        const hasAccel = e.metaKey || e.ctrlKey;
        if (!hasAccel || e.altKey) return;

        const key = e.key;
        const isZoomIn = key === '+' || key === '=' || key === 'Add';
        const isZoomOut = key === '-' || key === '_' || key === 'Subtract';
        const isZoomReset = key === '0' || key === ')';
        if (!isZoomIn && !isZoomOut && !isZoomReset) return;

        e.preventDefault();

        if (isZoomIn) {
            zoomUiIn({ showToast: true });
            return;
        }
        if (isZoomOut) {
            zoomUiOut({ showToast: true });
            return;
        }
        resetUiZoom({ showToast: true });
    });
}

function setupHelpMenuLinks() {
    tauriAPI.onMenuHelpReportIssue(() => {
        openExternal('https://github.com/ulyngs/redd-block/issues');
    }).catch(() => { });

    tauriAPI.onMenuHelpContactUs(() => {
        openExternal('mailto:team@reddfocus.org');
    }).catch(() => { });

    tauriAPI.onMenuHelpWhoWeAre(() => {
        openExternal('https://www.reddfocus.org/#team-anchor');
    }).catch(() => { });
}

// Setup Helper Settings in the settings modal
function setupHelperSettings() {
    if (isIOS) return;
    const statusIndicator = document.getElementById('helper-status-indicator');
    const cleanHostsBtn = document.getElementById('clean-hosts-btn');

    // Update helper status when settings modal opens
    ['settings-btn', 'settings-btn-stack']
        .map((id) => document.getElementById(id))
        .filter(Boolean)
        .forEach((settingsBtn) => {
            settingsBtn.addEventListener('click', () => {
                updateHelperStatusIndicator();
                updateCleanHostsBtnState();
                startHelperUiRefreshLoop();
            });
        });

    // Clean hosts file button
    if (cleanHostsBtn && !cleanHostsBtn._listenerAdded) {
        cleanHostsBtn._listenerAdded = true;
        cleanHostsBtn.addEventListener('click', async () => {
            if (cleanHostsBtn.disabled) return;

            const confirmed = await ask(
                'This will remove all ReDD Blocker entries from your system\'s hosts file. ' +
                'Only use this if websites remain blocked after all blocks have been stopped.\n\n' +
                'Your computer may ask for your password or show a security prompt.',
                { title: 'Clean hosts file?', kind: 'warning' }
            );
            if (!confirmed) return;

            cleanHostsBtn.disabled = true;
            const originalHTML = cleanHostsBtn.innerHTML;
            cleanHostsBtn.innerHTML = '<span class="btn-spinner"></span>Cleaning...';

            try {
                const result = await tauriAPI.cleanHostsFile();
                if (result.success) {
                    await message('Hosts file cleaned successfully. If websites were still blocked, they should now be accessible.', { title: 'Done', kind: 'info' });
                } else {
                    await message('Failed to clean hosts file: ' + (result.error || 'Unknown error'), { title: 'Error', kind: 'error' });
                }
            } catch (e) {
                console.error('Error cleaning hosts file:', e);
                await message('Error cleaning hosts file: ' + e.message, { title: 'Error', kind: 'error' });
            } finally {
                cleanHostsBtn.disabled = false;
                cleanHostsBtn.innerHTML = originalHTML;
                updateCleanHostsBtnState();
            }
        });
    }

}

function getHelperStatusDisplay(status) {
    const isRunning = !!status.running;
    const needsUpdate = isRunning && !status.version_ok;
    const installedButStopped = !!(status.installed && !isRunning);
    const enforcingNow = isRunning && status.version_ok && isDesktopBlockingEnforcedNow();

    if (isRunning && status.version_ok) {
        return {
            helperReady: true,
            indicatorClass: 'running',
            statusKey: enforcingNow ? 'helperStatusActive' : 'helperStatusIdle',
            showUpdate: false,
            showRemove: true,
            removeTitle: '',
            reachable: true,
        };
    }

    if (needsUpdate) {
        return {
            helperReady: false,
            indicatorClass: 'running',
            statusKey: 'helperStatusUpdateAvailable',
            showUpdate: true,
            showRemove: true,
            removeTitle: '',
            reachable: true,
        };
    }

    if (installedButStopped) {
        return {
            helperReady: false,
            indicatorClass: 'stopped',
            statusKey: 'helperStatusInstalledNotReachable',
            showUpdate: false,
            showRemove: true,
            removeTitle: tSettings('helperRemoveStaleHint'),
            reachable: false,
        };
    }

    return {
        helperReady: false,
        indicatorClass: 'stopped',
        statusKey: 'helperStatusNotInstalled',
        showUpdate: false,
        showRemove: false,
        removeTitle: '',
        reachable: false,
    };
}

function logHelperRemovalFallback(result) {
    if (result?.error) {
        console.warn('[helper-uninstall] Fallback cleanup used:', result.error);
    }
}


async function confirmHelperRemoved() {
    const status = await refreshDesktopHelperStatus();
    const removed = !(status?.installed || status?.running);

    await updateHelperStatusIndicator().catch(() => { });
    await checkHelperStatus().catch(() => { });

    if (!removed) {
        return {
            removed: false,
            status,
            error: 'ReDD Blocker could not confirm that the helper was fully removed. It still appears to be installed.'
        };
    }

    helperAvailable = false;
    return { removed: true, status };
}

async function uninstallHelperAndConfirmRemoved() {
    const result = await tauriAPI.uninstallHelper();
    if (!result.success) {
        return {
            success: false,
            error: result.error || 'Unknown error'
        };
    }

    logHelperRemovalFallback(result);

    const confirmation = await confirmHelperRemoved();
    if (!confirmation.removed) {
        return {
            success: false,
            error: confirmation.error
        };
    }

    return {
        success: true,
        usedFallback: !!result.error
    };
}

function isDesktopBlockingEnforcedNow() {
    if (isIOS) return false;
    return hasAnyEnforcedBlocks();
}

// Update helper status indicator in settings modal
async function updateHelperStatusIndicator() {
    const statusIndicator = document.getElementById('helper-status-indicator');
    if (!statusIndicator) return;

    const statusText = statusIndicator.querySelector('.status-text');
    const updateBtn = document.getElementById('update-helper-btn');

    try {
        const status = await refreshDesktopHelperStatus();
        const helperDisplay = getHelperStatusDisplay(status);
        helperAvailable = helperDisplay.helperReady;

        statusIndicator.classList.remove('running', 'stopped');
        statusIndicator.classList.add(helperDisplay.indicatorClass);
        statusText.textContent = tSettings(helperDisplay.statusKey);

        // Show/hide Update Helper button
        if (updateBtn) {
            updateBtn.style.display = helperDisplay.showUpdate ? 'flex' : 'none';

            // Wire up click handler (only once)
            if (!updateBtn._listenerAdded) {
                updateBtn._listenerAdded = true;
                updateBtn.addEventListener('click', async () => {
                    updateBtn.disabled = true;
                    const originalHTML = updateBtn.innerHTML;
                    updateBtn.innerHTML = '<span class="btn-spinner"></span>Updating...';
                    try {
                        const result = await tauriAPI.installHelper();
                        if (result.success) {
                            // Wait for helper to start up
                            await new Promise(resolve => setTimeout(resolve, 2000));
                            await updateHelperStatusIndicator();
                            await checkHelperStatus();
                        } else if (isHelperInstallCancelled(result?.error)) {
                            console.log('Helper update cancelled by user');
                        } else {
                            await message('Failed to update helper: ' + (result.error || 'Unknown error'), { title: 'Error', kind: 'error' });
                        }
                    } catch (e) {
                        console.error('Error updating helper:', e);
                        await message('Error updating helper: ' + e.message, { title: 'Error', kind: 'error' });
                    } finally {
                        updateBtn.disabled = false;
                        updateBtn.innerHTML = originalHTML;
                    }
                });
            }
        }

    } catch (e) {
        statusIndicator.classList.remove('running', 'stopped');
        statusIndicator.classList.add('stopped');
        statusText.textContent = tSettings('helperStatusUnknown');

        if (updateBtn) updateBtn.style.display = 'none';
    }

    // Also update Override All button visibility
    updateOverrideAllButtonVisibility();
}

// Update clean hosts button state (disabled when blocks are running)
function updateCleanHostsBtnState() {
    const btn = document.getElementById('clean-hosts-btn');
    if (!btn) return;
    const active = hasAnyActiveBlocks();
    btn.disabled = active;
    btn.title = active ? 'Stop all running blocks first' : '';
}

function getDiagValue(diag, ...keys) {
    for (const key of keys) {
        if (diag && diag[key] !== undefined && diag[key] !== null) {
            return diag[key];
        }
    }
    return undefined;
}

function getPrettyPrintedDiagnosticsJson(rawText) {
    if (!rawText) return '(unavailable)';
    try {
        return JSON.stringify(JSON.parse(rawText), null, 2);
    } catch (e) {
        return rawText;
    }
}

function buildDiagnosticsReport(diag) {
    const osName = getDiagValue(diag, 'os_name', 'osName')
        || (navigator.platform?.startsWith('Mac') ? 'macOS' : navigator.platform?.startsWith('Win') ? 'Windows' : 'unknown');
    const arch = getDiagValue(diag, 'arch') || 'unknown';
    const appVersion = document.getElementById('settings-version')?.textContent || '';
    const installed = !!getDiagValue(diag, 'helper_installed', 'helperInstalled');
    const running = !!getDiagValue(diag, 'helper_running', 'helperRunning');
    const version = getDiagValue(diag, 'helper_version', 'helperVersion') || 'Unknown';
    const versionOk = !!getDiagValue(diag, 'helper_version_ok', 'helperVersionOk');
    const expectedVersion = getDiagValue(diag, 'expected_helper_version', 'expectedHelperVersion') || 'unknown';
    const hostsFile = getDiagValue(diag, 'hosts_file', 'hostsFile') || '(unavailable)';
    const hostsPath = getDiagValue(diag, 'hosts_path', 'hostsPath') || '(unknown)';
    const stateFile = getDiagValue(diag, 'helper_state_file', 'helperStateFile') || '(unavailable)';
    const statePath = getDiagValue(diag, 'helper_state_path', 'helperStatePath') || '(unknown)';
    const helperLogTail = getDiagValue(diag, 'helper_log_tail', 'helperLogTail');
    const helperLogPath = getDiagValue(diag, 'helper_log_path', 'helperLogPath');
    const installLogTail = getDiagValue(diag, 'install_log_tail', 'installLogTail');
    const installLogPath = getDiagValue(diag, 'install_log_path', 'installLogPath');
    const helperDisplay = getHelperStatusDisplay({ installed, running, version_ok: versionOk });
    const helperStatusLabel = tSettings(helperDisplay.statusKey);
    const reachable = !!running;

    return {
        osName,
        arch,
        appVersion,
        installed,
        running,
        reachable,
        version,
        versionOk,
        expectedVersion,
        helperStatusLabel,
        helperDisplay,
        hostsFile,
        hostsPath,
        hasReddBlock: hostsFile.includes('BEGIN REDD BLOCK'),
        statePretty: getPrettyPrintedDiagnosticsJson(stateFile),
        statePath,
        helperLogTail,
        helperLogPath,
        installLogTail,
        installLogPath,
    };
}

function formatDiagnosticsText(diag) {
    const report = buildDiagnosticsReport(diag);
    return [
        '=== System ===',
        `OS: ${report.osName}`,
        `Architecture: ${report.arch}`,
        report.appVersion ? `App version: ${report.appVersion}` : '',
        '',
        '=== Helper Daemon ===',
        `Status: ${report.helperStatusLabel}`,
        `Installed: ${report.installed ? 'Yes' : 'No'}`,
        `Reachable: ${report.reachable ? 'Yes' : 'No'}`,
        `Running: ${report.running ? 'Yes' : 'No'}`,
        `Version OK: ${report.versionOk ? 'Yes' : 'No'}`,
        `Version: ${report.version}`,
        `Expected version: ${report.expectedVersion}`,
        '',
        '=== Paths ===',
        `Hosts file: ${report.hostsPath}`,
        `Helper state file: ${report.statePath}`,
        report.helperLogPath ? `Helper log: ${report.helperLogPath}` : '',
        report.installLogPath ? `Install log: ${report.installLogPath}` : '',
        '',
        '=== Hosts File ===',
        report.hostsFile.trim(),
        '',
        '=== Helper State File ===',
        report.statePretty.trim(),
        report.helperLogTail ? '' : undefined,
        report.helperLogTail ? '=== Helper Log Tail ===' : undefined,
        report.helperLogTail ? report.helperLogTail.trim() : undefined,
        report.installLogTail ? '' : undefined,
        report.installLogTail ? '=== Install Log Tail ===' : undefined,
        report.installLogTail ? report.installLogTail.trim() : undefined,
    ].filter(line => line !== undefined).join('\n');
}

function captureDiagnosticsScrollState(content) {
    if (!content) return null;
    return {
        contentScrollTop: content.scrollTop,
        preScrollTops: Array.from(content.querySelectorAll('.diagnostics-pre')).map(el => el.scrollTop),
    };
}

function restoreDiagnosticsScrollState(content, scrollState) {
    if (!content || !scrollState) return;
    content.scrollTop = scrollState.contentScrollTop || 0;
    const preEls = Array.from(content.querySelectorAll('.diagnostics-pre'));
    preEls.forEach((el, idx) => {
        el.scrollTop = scrollState.preScrollTops?.[idx] || 0;
    });
}

async function refreshDiagnosticsModalContent({ showLoading = false, loadingDelayMs = 0 } = {}) {
    const modal = document.getElementById('diagnostics-modal');
    const content = document.getElementById('diagnostics-content');
    if (!modal || !content) return;

    const scrollState = showLoading ? null : captureDiagnosticsScrollState(content);
    let loadingShown = false;
    let loadingTimer = null;
    let loadingCancelled = false;
    if (showLoading && loadingDelayMs > 0) {
        loadingTimer = setTimeout(() => {
            if (loadingCancelled) return;
            content.innerHTML = '<div class="diagnostics-loading">Loading…</div>';
            loadingShown = true;
        }, loadingDelayMs);
    } else if (showLoading) {
        content.innerHTML = '<div class="diagnostics-loading">Loading…</div>';
        loadingShown = true;
    }

    const stopLoadingTimer = () => {
        loadingCancelled = true;
        if (loadingTimer) {
            clearTimeout(loadingTimer);
            loadingTimer = null;
        }
    };

    let diag = null;
    let enforcementEnabled = false;
    try {
        const diagnosticsTimeoutMs = 20_000;
        diag = await Promise.race([
            invoke('get_system_diagnostics'),
            new Promise((_, reject) => {
                setTimeout(
                    () => reject(new Error('Diagnostics timed out — try Refresh')),
                    diagnosticsTimeoutMs,
                );
            }),
        ]);
        try {
            enforcementEnabled = !!(await invoke('get_enforcement_enabled'));
        } catch (_) { /* non-desktop */ }
        stopLoadingTimer();
        content.innerHTML = renderSystemDiagnostics(diag, { enforcementEnabled });
        updateDiagnosticsModalChrome(diag);
        if (!loadingShown) {
            restoreDiagnosticsScrollState(content, scrollState);
        }
    } catch (e) {
        stopLoadingTimer();
        content.innerHTML = `<div class="diagnostics-error">Failed to load diagnostics: ${escapeHtml(e.message || e)}</div>`;
        updateDiagnosticsModalChrome(null);
    }

    const copyBtn = document.getElementById('diagnostics-copy-btn');
    const copyLabel = document.getElementById('diagnostics-copy-btn-label');
    if (copyBtn) {
        copyBtn.onclick = () => {
            if (!diag) {
                if (copyLabel) copyLabel.textContent = tSettings('diagnosticsCopyFailed');
                return;
            }
            const text = JSON.stringify(diag, null, 2);
            navigator.clipboard.writeText(text).then(() => {
                if (copyLabel) copyLabel.textContent = tSettings('diagnosticsCopied');
                setTimeout(() => {
                    if (copyLabel) copyLabel.textContent = tSettings('diagnosticsCopyReport');
                }, 2000);
            }).catch(() => {
                if (copyLabel) copyLabel.textContent = tSettings('diagnosticsCopyFailed');
                setTimeout(() => {
                    if (copyLabel) copyLabel.textContent = tSettings('diagnosticsCopyReport');
                }, 2000);
            });
        };
    }
}

function updateDiagnosticsModalChrome(diag) {
    const versionEl = document.getElementById('diagnostics-version-label');

    if (versionEl) {
        versionEl.textContent = diag?.app?.version ? `v${diag.app.version}` : '';
    }
}

function diagnosticsStatusDot(state) {
    if (state === 'ok') return '<span class="diagnostics-status-dot ok" aria-hidden="true">✓</span>';
    if (state === 'off') return '<span class="diagnostics-status-dot off" aria-hidden="true">✗</span>';
    return '<span class="diagnostics-status-dot na" aria-hidden="true"></span>';
}

function diagnosticsTriState(values) {
    if (!values.length) return 'off';
    if (values.every(v => v === true)) return 'ok';
    if (values.some(v => v === false)) return 'off';
    return 'na';
}

function diagnosticsBrowserProfiles(key, b) {
    const profiles = b?.profiles || [];
    if (key === 'safari') return profiles;
    const def = profiles.find(p => p.isDefault) || profiles[0];
    return def ? [def] : [];
}

// Extension setup from on-disk profile scan — independent of whether the browser is running.
function diagnosticsBrowserExtensionState(key, b) {
    const profiles = diagnosticsBrowserProfiles(key, b);
    return {
        installed: diagnosticsTriState(profiles.map(p => p.installed)),
        enabled: diagnosticsTriState(profiles.map(p => p.enabled)),
        privateBrowsing: diagnosticsTriState(profiles.map(p => p.privateBrowsing)),
    };
}

function diagnosticsAutomationEntry(d, key) {
    const label = BROWSER_STORE_LINKS[key]?.label || key;
    const list = d.automation?.browsers || [];
    const entry = list.find((b) => String(b.label || '').toLowerCase() === key);
    return entry?.state || 'unknown';
}

function diagnosticsAutomationStatusCell(state) {
    const normalized = String(state || 'unknown').toLowerCase();
    let label;
    if (normalized === 'granted') label = tSettings('diagnosticsAutomationGranted');
    else if (normalized === 'denied') label = tSettings('diagnosticsAutomationDenied');
    else label = tSettings('diagnosticsAutomationUnknown');
    const dotState = normalized === 'granted' ? 'ok' : (normalized === 'denied' ? 'off' : 'na');
    return `<span class="diagnostics-status-cell">${diagnosticsStatusDot(dotState)}<span class="diag-muted">${escapeHtml(label)}</span></span>`;
}

function diagnosticsKvRow(label, valueHtml) {
    return `<div class="diagnostics-kv-row"><span class="diagnostics-kv-label">${label}</span><span class="diagnostics-kv-value">${valueHtml}</span></div>`;
}

function diagnosticsKvPreRow(label, lines, escape) {
    const value = lines.length > 0
        ? `<pre class="diagnostics-pre diagnostics-pre-inline">${escape(lines.join('\n'))}</pre>`
        : `<span class="diag-muted">—</span>`;
    return `<div class="diagnostics-kv-row diagnostics-kv-row-multiline"><span class="diagnostics-kv-label">${label}</span><span class="diagnostics-kv-value">${value}</span></div>`;
}

function diagnosticsYesNoValue(yes) {
    return `<span class="${yes ? 'diag-ok' : ''}">${yes ? tSettings('diagnosticsYes') : tSettings('diagnosticsNo')}</span>`;
}

function diagnosticsOkNoValue(yes) {
    return `<span class="${yes ? 'diag-ok' : 'diag-error'}">${yes ? tSettings('diagnosticsYes') : tSettings('diagnosticsNo')}</span>`;
}

// Render the structured SystemDiagnostics struct as HTML sections.
// Designed for both user-readable scan AND copy-as-JSON for support.
function renderSystemDiagnostics(d, { enforcementEnabled = false } = {}) {
    const fmtTs = (ms) => ms ? new Date(ms).toLocaleString() : '—';
    const e = (s) => escapeHtml(String(s));
    let html = '';

    // App (version lives in the modal header)
    html += '<div class="diagnostics-section">';
    html += `<div class="diagnostics-section-title">${e(tSettings('diagnosticsAppSection'))}</div>`;
    html += '<div class="diagnostics-card">';
    html += diagnosticsKvRow(e(tSettings('diagnosticsOsArch')), `${e(d.app.os)} / ${e(d.app.arch)}`);
    html += '</div></div>';

    // Currently being blocked / current enforcement
    if (d.current_blocking) {
        const cb = d.current_blocking;
        const hasAllowlist = (cb.blocks || []).some((b) => b.mode === 'allowlist')
            || (cb.allowed_domains?.length ?? 0) > 0
            || cb.allowlist_active;
        const sectionTitleKey = hasAllowlist
            ? 'diagnosticsCurrentEnforcement'
            : 'diagnosticsCurrentlyBlocking';
        html += '<div class="diagnostics-section">';
        html += `<div class="diagnostics-section-title">${e(tSettings(sectionTitleKey))}</div>`;
        html += '<div class="diagnostics-card diagnostics-card-enforcement">';
        if (cb.blocks && cb.blocks.length > 0) {
            html += '<ul class="diagnostics-list">';
            for (const b of cb.blocks) {
                const label = `${b.emoji ? b.emoji + ' ' : ''}${b.name || b.blocklistId}`;
                const isAllow = b.mode === 'allowlist';
                const modeLabel = isAllow
                    ? tSettings('diagnosticsModeAllowlist')
                    : tSettings('diagnosticsModeBlocklist');
                const srcLabel = b.source === 'schedule' ? 'schedule' : 'one-off';
                const endsTxt = b.endsAt ? ` until ${new Date(b.endsAt).toLocaleString()}` : '';
                const domainsCount = (b.domains || []).length;
                let detail = `${modeLabel} · ${srcLabel}${endsTxt}`;
                if (domainsCount > 0) {
                    detail += ` · ${tSettingsFmt('diagnosticsBlockDomainsFmt', { n: domainsCount })}`;
                }
                const appsCount = (b.apps || []).length;
                if (appsCount > 0) {
                    detail += ` · ${tSettingsFmt('diagnosticsBlockAppsFmt', { n: appsCount })}`;
                }
                html += `<li class="diagnostics-kv-row diagnostics-kv-row-multiline"><span class="diagnostics-kv-label">${e(label)}</span><span class="diagnostics-kv-value diag-muted">${e(detail)}</span></li>`;
            }
            html += '</ul>';
        } else {
            html += diagnosticsKvRow(
                e(tSettings('diagnosticsActiveSources')),
                `<span class="diag-muted">${e(tSettings('diagnosticsActiveSourcesNone'))}</span>`,
            );
        }
        html += diagnosticsKvPreRow(
            e(tSettings('diagnosticsDomainsCount').replace('{n}', String(cb.domains?.length ?? 0))),
            cb.domains || [],
            e,
        );
        const allowedDomains = cb.allowed_domains || [];
        if (allowedDomains.length > 0 || (cb.blocks || []).some((b) => b.mode === 'allowlist')) {
            html += diagnosticsKvPreRow(
                e(tSettings('diagnosticsAllowedDomainsCount').replace('{n}', String(allowedDomains.length))),
                allowedDomains,
                e,
            );
        }
        html += diagnosticsKvPreRow(
            e(tSettings('diagnosticsAppsCount').replace('{n}', String(cb.apps?.length ?? 0))),
            cb.apps || [],
            e,
        );
        const allowedApps = cb.allowed_apps || [];
        if (allowedApps.length > 0 || cb.allowlist_active) {
            html += diagnosticsKvPreRow(
                e(tSettings('diagnosticsAllowedAppsCount').replace('{n}', String(allowedApps.length))),
                allowedApps,
                e,
            );
            html += diagnosticsKvRow(
                e(tSettings('diagnosticsAllowlistEnforcement')),
                diagnosticsYesNoValue(!!cb.allowlist_active),
            );
        }
        html += '</div></div>';
    }

    // Migration
    const m = d.migration;
    html += '<div class="diagnostics-section">';
    html += `<div class="diagnostics-section-title">${e(tSettings('diagnosticsMigrationSection'))}</div>`;
    html += '<div class="diagnostics-card">';
    html += diagnosticsKvRow(e(tSettings('diagnosticsWasV1x')), diagnosticsYesNoValue(!!m.came_from_v1x));
    if (m.residue_items && m.residue_items.length > 0) {
        html += diagnosticsKvRow(e(tSettings('diagnosticsLeftoverFiles')), `<span class="diag-error">${m.residue_items.length} found</span>`);
        html += '<ul class="diagnostics-list">';
        for (const item of m.residue_items) {
            html += `<li class="diag-error">${e(item)}</li>`;
        }
        html += '</ul>';
    } else {
        html += diagnosticsKvRow(
            e(tSettings('diagnosticsLeftoverFiles')),
            `<span class="diag-ok">${e(tSettings('diagnosticsFullyMigrated'))}</span>`,
        );
    }
    html += diagnosticsKvRow(e(tSettings('diagnosticsStampedVersion')), `<span class="diag-muted">${e(m.ran_at_version || '—')}</span>`);
    html += diagnosticsKvRow(e(tSettings('diagnosticsStampedAt')), `<span class="diag-muted">${e(fmtTs(m.ran_at_ms))}</span>`);
    html += '</div></div>';

    // Full Disk Access (macOS)
    if (d.fda?.applicable) {
        const f = d.fda;
        const choiceLabel = f.onboarding_choice || tSettings('diagnosticsMarkerNotSet');
        html += '<div class="diagnostics-section">';
        html += `<div class="diagnostics-section-title">${e(tSettings('diagnosticsFullDiskAccess'))}</div>`;
        html += '<div class="diagnostics-card">';
        html += diagnosticsKvRow(e(tSettings('diagnosticsFdaLiveGranted')), diagnosticsOkNoValue(f.live_granted === true));
        html += diagnosticsKvRow(
            e(tSettings('diagnosticsSafariPlistReadable')),
            f.safari_plist_readable == null
                ? '<span class="diag-muted">—</span>'
                : diagnosticsOkNoValue(f.safari_plist_readable === true),
        );
        html += diagnosticsKvRow(e(tSettings('diagnosticsOnboardingMarker')), `<span class="diag-muted">${e(choiceLabel)}</span>`);
        if (f.safariNeedsFdaAccess != null) {
            const fdaRequired = f.safariNeedsFdaAccess === true;
            html += diagnosticsKvRow(
                e(tSettings('diagnosticsSafariFdaRequired')),
                fdaRequired
                    ? `<span class="diag-error">${e(tSettings('diagnosticsYes'))}</span>`
                    : `<span class="diag-ok">${e(tSettings('diagnosticsNo'))}</span>`,
            );
        }
        html += '</div></div>';
    }

    // Automation (macOS)
    if (d.automation?.applicable) {
        html += '<div class="diagnostics-section">';
        html += `<div class="diagnostics-section-title">${e(tSettings('diagnosticsAutomationSection'))}</div>`;
        html += `<p class="diagnostics-section-desc">${e(tSettings('diagnosticsAutomationSectionHint'))}</p>`;
        html += '<div class="diagnostics-card diagnostics-table-wrap"><table class="diagnostics-table diagnostics-table-labeled-status"><thead><tr>';
        html += `<th>${e(tSettings('diagnosticsThBrowser'))}</th>`;
        html += `<th>${e(tSettings('diagnosticsThAutomation'))}</th>`;
        html += '</tr></thead><tbody>';
        for (const key of ['safari', 'chrome', 'brave', 'edge']) {
            const b = d.browsers[key];
            if (!b?.installed) continue;
            if (key !== 'safari' && !browserUsesAutomation(key)) continue;
            const label = BROWSER_STORE_LINKS[key]?.label || key;
            const autoState = diagnosticsAutomationEntry(d, key);
            html += '<tr>';
            html += `<td><div class="diagnostics-browser-cell"><img class="diagnostics-browser-icon" src="${browserIconUrl(key)}" alt="" width="20" height="20">${e(label)}</div></td>`;
            html += `<td>${diagnosticsAutomationStatusCell(autoState)}</td>`;
            html += '</tr>';
        }
        html += '</tbody></table></div></div>';
    }

    // Browsers (extension)
    const extensionBrowserKeys = isMacOSDesktop
        ? ['firefox', ...MAC_BLOCKING_METHOD_KEYS.filter((k) => browserBlockingMethod(k) === 'extension')]
        : ['chrome', 'brave', 'edge', 'firefox', 'safari'];
    const browsersHint = isMacOSDesktop
        ? tSettings('diagnosticsBrowsersSectionHintMacExtension')
        : tSettings('diagnosticsBrowsersSectionHint');
    html += '<div class="diagnostics-section">';
    html += `<div class="diagnostics-section-title">${e(tSettings('diagnosticsBrowsersSection'))}</div>`;
    html += `<p class="diagnostics-section-desc">${e(browsersHint)}</p>`;
    html += '<div class="diagnostics-card diagnostics-table-wrap"><table class="diagnostics-table"><thead><tr>';
    html += `<th>${e(tSettings('diagnosticsThBrowser'))}</th>`;
    html += `<th>${e(tSettings('diagnosticsThExtInstalled'))}</th>`;
    html += `<th>${e(tSettings('diagnosticsThExtEnabled'))}</th>`;
    html += `<th>${e(tSettings('diagnosticsThExtPrivate'))}</th>`;
    html += '</tr></thead><tbody>';
    for (const key of extensionBrowserKeys) {
        const b = d.browsers[key];
        if (!b?.installed) continue;
        const label = BROWSER_STORE_LINKS[key]?.label || key;
        const ext = diagnosticsBrowserExtensionState(key, b);
        html += '<tr>';
        html += `<td><div class="diagnostics-browser-cell"><img class="diagnostics-browser-icon" src="${browserIconUrl(key)}" alt="" width="20" height="20">${e(label)}</div></td>`;
        html += `<td>${diagnosticsStatusDot(ext.installed)}</td>`;
        html += `<td>${diagnosticsStatusDot(ext.enabled)}</td>`;
        html += `<td>${diagnosticsStatusDot(ext.privateBrowsing)}</td>`;
        html += '</tr>';
    }
    html += '</tbody></table></div></div>';

    // Enforcement
    html += '<div class="diagnostics-section">';
    html += `<div class="diagnostics-section-title">${e(tSettings('diagnosticsEnforcementSection'))}</div>`;
    html += '<div class="diagnostics-card">';
    if (!isIOS) {
        const forceLabel = enforcementEnabled
            ? tSettings('diagnosticsForceCloseEnabled')
            : tSettings('diagnosticsForceCloseDisabled');
        const forceClass = enforcementEnabled ? 'diag-ok' : 'diag-muted';
        html += diagnosticsKvRow(
            e(tSettings('diagnosticsForceClose')),
            `<span class="${forceClass}">${e(forceLabel)}</span>`,
        );
    }
    html += diagnosticsKvRow(e(tSettings('diagnosticsGracePeriod')), `${e(d.enforcer.grace_seconds)} s`);
    if (d.watchdog) {
        html += diagnosticsKvRow(e(tSettings('diagnosticsWatchdog')), diagnosticsYesNoValue(d.watchdog.task_present));
    }
    html += '</div></div>';

    // Recent log
    if (d.recent_log && d.recent_log.length > 0) {
        html += '<div class="diagnostics-section">';
        html += `<div class="diagnostics-section-title">${e(tSettings('diagnosticsRecentLogSection').replace('{n}', String(d.recent_log.length)))}</div>`;
        html += '<div class="diagnostics-card">';
        html += `<pre class="diagnostics-pre">${e(d.recent_log.join('\n'))}</pre>`;
        html += '</div></div>';
    }

    // App data (redd-block-data.json)
    if (d.app_data) {
        html += '<div class="diagnostics-section">';
        html += `<div class="diagnostics-section-title">${e(tSettings('diagnosticsAppDataSection'))}</div>`;
        html += '<div class="diagnostics-card">';
        if (d.app_data.path) {
            html += diagnosticsKvRow(e(tSettings('diagnosticsPath')), `<span class="diag-muted">${e(d.app_data.path)}</span>`);
        }
        if (d.app_data.error) {
            html += `<div class="diagnostics-kv-row"><span class="diagnostics-kv-value diag-error">${e(d.app_data.error)}</span></div>`;
        }
        if (d.app_data.pretty_json) {
            html += `<pre class="diagnostics-pre">${e(d.app_data.pretty_json)}</pre>`;
        }
        html += '</div></div>';
    }

    return html;
}

// Diagnostics modal
function setDiagnosticsButtonLoading(loading) {
    const btn = document.getElementById('diagnostics-btn');
    const label = document.getElementById('settings-diagnostics-btn-label');
    if (!btn || !label) return;

    const icon = btn.querySelector('svg');
    let spinner = btn.querySelector('.diagnostics-btn-spinner');

    if (loading) {
        btn.disabled = true;
        btn.setAttribute('aria-busy', 'true');
        if (icon) icon.classList.add('hidden');
        if (!spinner) {
            spinner = document.createElement('span');
            spinner.className = 'btn-spinner diagnostics-btn-spinner';
            spinner.setAttribute('aria-hidden', 'true');
            btn.insertBefore(spinner, label);
        } else {
            spinner.classList.remove('hidden');
        }
        label.textContent = tSettings('diagnosticsLoadingBtn');
    } else {
        btn.disabled = false;
        btn.removeAttribute('aria-busy');
        if (icon) icon.classList.remove('hidden');
        if (spinner) spinner.classList.add('hidden');
        label.textContent = tSettings('settingsDiagnosticsBtn');
    }
}

function closeDiagnosticsModal() {
    const modal = document.getElementById('diagnostics-modal');
    const settingsModal = document.getElementById('settings-modal');
    if (!modal) return;
    modal.classList.add('hidden');
    if (modal.dataset.settingsWasOpen === '1') {
        settingsModal?.classList.remove('hidden');
        startHelperUiRefreshLoop();
    }
    delete modal.dataset.settingsWasOpen;
}

async function openDiagnosticsModal() {
    const modal = document.getElementById('diagnostics-modal');
    const content = document.getElementById('diagnostics-content');
    const settingsModal = document.getElementById('settings-modal');
    if (!modal || !content) return;
    if (modal.dataset.opening === '1') return;

    modal.dataset.opening = '1';
    const settingsWasOpen = !!(settingsModal && !settingsModal.classList.contains('hidden'));
    modal.dataset.settingsWasOpen = settingsWasOpen ? '1' : '';

    modal.classList.add('hidden');
    setDiagnosticsButtonLoading(true);

    const closeBtn = document.getElementById('close-diagnostics-btn');
    if (closeBtn) {
        closeBtn.onclick = closeDiagnosticsModal;
    }
    modal.onclick = (e) => {
        if (e.target === modal) {
            closeDiagnosticsModal();
        }
    };

    try {
        await refreshDiagnosticsModalContent({ showLoading: false });
        if (settingsWasOpen) {
            settingsModal.classList.add('hidden');
            stopHelperUiRefreshLoop();
        }
        modal.classList.remove('hidden');
    } catch (_) {
        if (settingsWasOpen) {
            settingsModal.classList.add('hidden');
            stopHelperUiRefreshLoop();
        }
        modal.classList.remove('hidden');
    } finally {
        setDiagnosticsButtonLoading(false);
        delete modal.dataset.opening;
    }
}

async function refreshDiagnosticsModalManual() {
    const btn = document.getElementById('diagnostics-refresh-btn');
    if (btn?.disabled) return;
    if (btn) btn.disabled = true;
    try {
        // Modal is already open — swap to loading only if the fetch is slow
        // enough that stale content would mislead; fast refresh updates in place.
        await refreshDiagnosticsModalContent({ showLoading: true, loadingDelayMs: 400 });
    } finally {
        if (btn) btn.disabled = false;
    }
}

// Setup, onboarding replay, and diagnostics from Settings → Help.
function setupSettingsHelpButtons() {
    const setupBtn = document.getElementById('settings-setup-btn');
    if (setupBtn && !setupBtn.dataset.wired) {
        setupBtn.dataset.wired = '1';
        setupBtn.addEventListener('click', () => {
            openExtensionSetupOverlay().catch((e) => {
                console.warn('[settings-help] setup overlay failed:', e);
            });
        });
    }

    const onboardingBtn = document.getElementById('settings-onboarding-btn');
    if (onboardingBtn && !onboardingBtn.dataset.wired) {
        onboardingBtn.dataset.wired = '1';
        onboardingBtn.addEventListener('click', () => {
            restartOnboardingFromSettings().catch((e) => {
                console.warn('[settings-help] onboarding replay failed:', e);
            });
        });
    }

    const diagnosticsBtn = document.getElementById('diagnostics-btn');
    if (diagnosticsBtn && !diagnosticsBtn.dataset.wired) {
        diagnosticsBtn.dataset.wired = '1';
        diagnosticsBtn.addEventListener('click', openDiagnosticsModal);
    }

    const diagnosticsRefreshBtn = document.getElementById('diagnostics-refresh-btn');
    if (diagnosticsRefreshBtn && !diagnosticsRefreshBtn.dataset.wired) {
        diagnosticsRefreshBtn.dataset.wired = '1';
        diagnosticsRefreshBtn.addEventListener('click', () => {
            void refreshDiagnosticsModalManual();
        });
    }
}

// Any blocks or schedules the user could clear via Stop All — includes
// future scheduled segments, not only what is enforcing right now.
function hasAnyActiveBlocks() {
    return hasAnyBlockingStateToClear();
}

// Manage section: macOS and Windows always show Uninstall guidance; Stop All when relevant.
function updateManageSectionVisibility() {
    const section = document.getElementById('settings-manage-section');
    if (!section) return;
    const isMac = document.body.classList.contains('mac');
    const isWindows = document.body.classList.contains('windows');
    const showOverride = hasAnyBlockingStateToClear();
    section.classList.toggle('hidden', !isMac && !isWindows && !showOverride);
}

// Show Stop All while there are active blocks or schedules to clear.
function updateOverrideAllButtonVisibility() {
    const row = document.getElementById('settings-override-all-row');
    const showOverride = hasAnyBlockingStateToClear();

    if (row) row.classList.toggle('hidden', !showOverride);
    updateManageSectionVisibility();
    updateGraceSettingLock();
}

// Show challenge for removing helper when blocks are active


// Variable to track override-all challenge text
let overrideAllChallengeText = '';
let overrideAllWordChallengeState = null;

// Setup the configurable browser-extension grace period.
// Backend reads `settings.extensionGraceSeconds` from the data file
// on every grace-start (no app restart needed). Backend rejects
// increases when at least one block is currently active.
// ---- Installed Apps Picker Modal ------------------------------------------
// Shows a searchable list of installed apps (scanned from Start Menu on
// Windows, /Applications on macOS) so users don't have to navigate the
// OS file picker to find executables.

let installedAppsCache = null; // Cache the list so we don't re-scan every open

async function openInstalledAppsPicker() {
    const modal = document.getElementById('app-picker-modal');
    const listEl = document.getElementById('app-picker-list');
    const searchInput = document.getElementById('app-picker-search');
    const addBtn = document.getElementById('app-picker-add-btn');
    const cancelBtn = document.getElementById('app-picker-cancel-btn');
    const browseBtn = document.getElementById('app-picker-browse-btn');

    if (!modal || !listEl) return;

    // Show modal with loading state
    modal.classList.remove('hidden');
    searchInput.value = '';
    listEl.innerHTML = '<div class="app-picker-loading">Scanning installed apps...</div>';

    // Fetch installed apps (cached after first call)
    await ensureInstalledAppsCache();
    if (!installedAppsCache) {
        listEl.innerHTML = '<div class="app-picker-empty">Could not scan installed apps. Use "Browse manually..." below.</div>';
    }

    const apps = installedAppsCache || [];
    const selectedProcessNames = new Set();

    function sameAppPickerName(displayName, processName) {
        const normalize = (value) => String(value || '').trim().toLocaleLowerCase();
        return normalize(displayName) === normalize(processName);
    }

    function renderAppList(filter = '') {
        const lowerFilter = filter.toLowerCase();
        const filtered = filter
            ? apps.filter(a =>
                a.display_name.toLowerCase().includes(lowerFilter) ||
                a.process_name.toLowerCase().includes(lowerFilter))
            : apps;

        if (filtered.length === 0) {
            listEl.innerHTML = filter
                ? '<div class="app-picker-empty">No apps match your search</div>'
                : '<div class="app-picker-empty">No installed apps found</div>';
            return;
        }

        listEl.innerHTML = filtered.map(app => {
            const alreadyAdded = window.getModalApps().some(a => a.toLowerCase() === app.process_name.toLowerCase());
            const isChecked = selectedProcessNames.has(app.process_name) || alreadyAdded;
            const checkedClass = isChecked ? ' checked' : '';
            const checkedAttr = isChecked ? ' checked' : '';
            const disabledAttr = alreadyAdded ? ' disabled' : '';
            const dimStyle = alreadyAdded ? ' style="opacity: 0.5;"' : '';
            const processLine = sameAppPickerName(app.display_name, app.process_name)
                ? ''
                : `<div class="app-picker-item-process">${escapeHtml(app.process_name)}</div>`;

            return `<label class="app-picker-item${checkedClass}"${dimStyle}>
                <input type="checkbox" data-process="${escapeHtml(app.process_name)}"${checkedAttr}${disabledAttr}>
                <div class="app-picker-item-info">
                    <div class="app-picker-item-name">${escapeHtml(app.display_name)}</div>
                    ${processLine}
                </div>
            </label>`;
        }).join('');

        // Attach checkbox handlers
        listEl.querySelectorAll('input[type="checkbox"]').forEach(cb => {
            if (cb.disabled) return;
            cb.addEventListener('change', () => {
                const proc = cb.dataset.process;
                if (cb.checked) {
                    selectedProcessNames.add(proc);
                } else {
                    selectedProcessNames.delete(proc);
                }
                cb.closest('.app-picker-item').classList.toggle('checked', cb.checked);
                updateAddButton();
            });
        });
    }

    function updateAddButton() {
        const newCount = [...selectedProcessNames].filter(
            p => !window.getModalApps().some(a => a.toLowerCase() === p.toLowerCase())
        ).length;
        addBtn.textContent = newCount > 0 ? `Add Selected (${newCount})` : 'Add Selected';
        addBtn.disabled = newCount === 0;
    }

    renderAppList();
    updateAddButton();

    // Search filtering
    const onSearch = () => renderAppList(searchInput.value);
    searchInput.addEventListener('input', onSearch);

    // Clean up and close
    function closePickerModal() {
        modal.classList.add('hidden');
        searchInput.removeEventListener('input', onSearch);
    }

    // Cancel
    const onCancel = () => closePickerModal();
    cancelBtn.onclick = onCancel;

    // Click overlay to close
    const onOverlayClick = (e) => {
        if (e.target === modal) closePickerModal();
    };
    modal.addEventListener('click', onOverlayClick);

    // Add Selected
    addBtn.onclick = () => {
        const toAdd = [...selectedProcessNames].filter(
            p => !window.getModalApps().some(a => a.toLowerCase() === p.toLowerCase())
        );
        if (toAdd.length > 0) {
            const toAddCopy = [...toAdd];
            pushModalUndo('app', () => {
                toAddCopy.forEach(a => {
                    const i = window.getModalApps().indexOf(a);
                    if (i !== -1) window.getModalApps().splice(i, 1);
                });
                window.renderModalTags();
            });
            for (const appName of toAdd) {
                window.getModalApps().push(appName);
            }
            window.renderModalTags();
        }
        closePickerModal();
    };

    // Browse manually — fall back to the OS file picker (desktop only)
    if (browseBtn) {
        browseBtn.classList.remove('hidden');
        browseBtn.onclick = async () => {
        closePickerModal();
        const appNames = await tauriAPI.openAppPicker();
        if (appNames && appNames.length > 0) {
            const toAdd = appNames.filter(n => !window.getModalApps().includes(n));
            if (toAdd.length > 0) {
                const toAddCopy = [...toAdd];
                pushModalUndo('app', () => {
                    toAddCopy.forEach(a => {
                        const i = window.getModalApps().indexOf(a);
                        if (i !== -1) window.getModalApps().splice(i, 1);
                    });
                    window.renderModalTags();
                });
            }
            for (const appName of appNames) {
                if (!window.getModalApps().includes(appName)) {
                    window.getModalApps().push(appName);
                }
            }
            window.renderModalTags();
        }
    };
    } else if (browseBtn) {
        browseBtn.classList.add('hidden');
    }

    // Focus search input
    requestAnimationFrame(() => searchInput.focus());
}

// Setup the configurable browser-extension grace period.
function setupGraceSetting() {
    const input = document.getElementById('grace-seconds-input');
    const errorEl = document.getElementById('grace-error');
    if (!input) return;

    const showError = (msg) => {
        if (!errorEl) return;
        errorEl.textContent = msg;
        errorEl.classList.toggle('hidden', !msg);
    };

    // Load current value and reflect locked state.
    const refresh = async () => {
        try {
            const secs = await invoke('get_extension_grace_seconds');
            input.value = secs;
            updateGraceSettingLock();
        } catch (e) {
            console.warn('[grace] read failed:', e);
        }
    };
    refresh();

    let lastGood = parseInt(input.value, 10) || 60;
    input.addEventListener('change', async () => {
        const now = Date.now();
        const nowDate = new Date(now);
        if (hasAnyEnforcedBlocks(now, nowDate)) {
            input.value = lastGood;
            updateGraceSettingLock();
            return;
        }

        const raw = parseInt(input.value, 10);
        if (!Number.isFinite(raw)) {
            input.value = lastGood;
            return;
        }
        const clamped = Math.max(5, Math.min(300, raw));
        input.value = clamped;
        try {
            const applied = await invoke('set_extension_grace_seconds', { seconds: clamped });
            input.value = applied;
            lastGood = applied;
            showError('');
        } catch (e) {
            const msg = typeof e === 'string' ? e : (e && e.message) || 'Could not update grace period.';
            showError(msg);
            input.value = lastGood;
        }
    });
}

// Setup Override All functionality in settings
function setupOverrideAll() {
    const overrideAllBtn = document.getElementById('override-all-btn');
    const overrideAllModal = document.getElementById('override-all-modal');
    const cancelOverrideAllBtn = document.getElementById('cancel-override-all-btn');
    const confirmOverrideAllBtn = document.getElementById('confirm-override-all-btn');
    const overrideAllChallengeInput = document.getElementById('override-all-challenge-input');
    const overrideAllChallengeWordInput = document.getElementById('override-all-challenge-word-input');
    const overrideAllProgressBar = document.getElementById('override-all-progress-bar');
    const overrideAllChallengeTextEl = document.getElementById('override-all-challenge-text');
    const overrideAllCurrentWordEl = document.getElementById('override-all-current-word');

    function getOverrideAllTypedValue() {
        return overrideAllWordChallengeState?.typedText ?? overrideAllChallengeInput.value;
    }

    function renderOverrideAllChallengeText(errorIndex = -1) {
        if (!overrideAllChallengeTextEl) return;
        if (errorIndex < 0 || errorIndex >= overrideAllChallengeText.length) {
            overrideAllChallengeTextEl.textContent = overrideAllChallengeText;
        } else {
            const before = escapeHtml(overrideAllChallengeText.slice(0, errorIndex));
            const errorChar = escapeHtml(overrideAllChallengeText[errorIndex]);
            const after = escapeHtml(overrideAllChallengeText.slice(errorIndex + 1));
            overrideAllChallengeTextEl.innerHTML = `${before}<span class="error-char">${errorChar}</span>${after}`;
        }
    }

    // Open override all modal
    if (overrideAllBtn && overrideAllModal) {
        overrideAllBtn.addEventListener('click', () => {
            // Close settings modal first
            document.getElementById('settings-modal').classList.add('hidden');
            setLanguagePickerOpen(false);

            const challengeTextEl = document.getElementById('override-all-challenge-text');
            const instructionEl = document.getElementById('override-all-instruction');

            if (!hasAnyBlockingStateToClear()) {
                // No blocks active — show dialog but skip the typing challenge
                overrideAllChallengeText = '';
                overrideAllWordChallengeState = null;
                setOverrideAllWordChallengeMode(false);
                if (challengeTextEl) challengeTextEl.style.display = 'none';
                if (overrideAllChallengeInput) overrideAllChallengeInput.style.display = 'none';
                if (overrideAllChallengeWordInput) overrideAllChallengeWordInput.style.display = 'none';
                if (instructionEl) instructionEl.style.display = 'none';
                const progressEl = overrideAllModal.querySelector('.challenge-progress');
                if (progressEl) progressEl.style.display = 'none';
                if (confirmOverrideAllBtn) confirmOverrideAllBtn.disabled = false;
                overrideAllModal.classList.remove('hidden');
                return;
            }

            // Restore challenge elements visibility
            if (challengeTextEl) challengeTextEl.style.display = '';
            if (instructionEl) instructionEl.style.display = '';
            const progressEl = overrideAllModal.querySelector('.challenge-progress');
            if (progressEl) progressEl.style.display = '';

            // Find the hardest challenge among active blocks and schedules
            const hardestDifficulty = findHardestChallenge();

            // Generate challenge text based on hardest difficulty
            overrideAllChallengeText = generateOverrideChallengeText(
                hardestDifficulty.type,
                hardestDifficulty.count,
                hardestDifficulty.customText
            );

            // Sanitize: remove linebreaks and collapse multiple spaces
            overrideAllChallengeText = overrideAllChallengeText.replace(/[\r\n]+/g, ' ').replace(/\s{2,}/g, ' ').trim();

            // Display challenge
            renderOverrideAllChallengeText();
            overrideAllChallengeInput.value = '';
            overrideAllChallengeWordInput.value = '';
            overrideAllWordChallengeState = isMobileWordByWordChallenge(hardestDifficulty)
                ? buildWordChallengeState(overrideAllChallengeText)
                : null;
            setOverrideAllWordChallengeMode(!!overrideAllWordChallengeState);
            if (overrideAllChallengeInput) overrideAllChallengeInput.style.display = overrideAllWordChallengeState ? 'none' : '';
            if (overrideAllChallengeWordInput) overrideAllChallengeWordInput.style.display = overrideAllWordChallengeState ? '' : 'none';
            overrideAllProgressBar.style.width = '0%';
            if (confirmOverrideAllBtn) confirmOverrideAllBtn.disabled = !!overrideAllWordChallengeState;

            overrideAllModal.classList.remove('hidden');
            requestAnimationFrame(() => {
                if (overrideAllWordChallengeState) {
                    renderOverrideAllWordChallengeState();
                    overrideAllChallengeWordInput?.focus();
                } else {
                    overrideAllChallengeInput?.focus();
                }
            });
        });
    }

    // Cancel override all
    if (cancelOverrideAllBtn && overrideAllModal) {
        cancelOverrideAllBtn.addEventListener('click', () => {
            overrideAllModal.classList.add('hidden');
            overrideAllChallengeText = '';
            overrideAllWordChallengeState = null;
            setOverrideAllWordChallengeMode(false);
            confirmOverrideAllBtn.disabled = false;
            // Re-open settings modal so user goes back to settings, not main screen
            document.getElementById('settings-modal').classList.remove('hidden');
        });
    }

    // Click outside to close
    if (overrideAllModal) {
        overrideAllModal.addEventListener('click', (e) => {
            if (e.target === overrideAllModal) {
                overrideAllModal.classList.add('hidden');
                overrideAllChallengeText = '';
                overrideAllWordChallengeState = null;
                setOverrideAllWordChallengeMode(false);
                confirmOverrideAllBtn.disabled = false;
                // Re-open settings modal so user goes back to settings, not main screen
                document.getElementById('settings-modal').classList.remove('hidden');
            }
        });
    }

    // Prevent paste
    if (overrideAllChallengeInput) {
        overrideAllChallengeInput.addEventListener('paste', (e) => {
            e.preventDefault();
        });

        // Update progress as user types
        overrideAllChallengeInput.addEventListener('input', () => {
            const typed = overrideAllChallengeInput.value;
            const target = overrideAllChallengeText;

            let correctChars = 0;
            let firstErrorIndex = -1;
            for (let i = 0; i < typed.length && i < target.length; i++) {
                if (typed[i] === target[i]) {
                    correctChars++;
                } else {
                    firstErrorIndex = i;
                    break;
                }
            }

            const progress = (correctChars / target.length) * 100;
            overrideAllProgressBar.style.width = `${progress}%`;

            renderOverrideAllChallengeText(firstErrorIndex);
        });

        // Enter key submits
        overrideAllChallengeInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                confirmOverrideAllBtn.click();
            }
        });
    }
    if (overrideAllChallengeWordInput) {
        overrideAllChallengeWordInput.addEventListener('paste', (e) => {
            e.preventDefault();
        });
        overrideAllChallengeWordInput.addEventListener('input', () => {
            if (!overrideAllWordChallengeState) return;
            overrideAllCurrentWordEl.textContent = getCurrentChallengeWord(overrideAllWordChallengeState);
        });
        overrideAllChallengeWordInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                confirmOverrideAllBtn.click();
            }
        });
    }

    // Confirm override all
    if (confirmOverrideAllBtn) {
        confirmOverrideAllBtn.addEventListener('click', async () => {
            if (overrideAllWordChallengeState) {
                const expectedWord = getCurrentChallengeWord(overrideAllWordChallengeState);
                const typedWord = overrideAllChallengeWordInput.value.trim();
                if (typedWord === expectedWord) {
                    overrideAllWordChallengeState.currentIndex++;
                    const completedText = getCompletedChallengeText(overrideAllWordChallengeState);
                    overrideAllWordChallengeState.typedText = overrideAllWordChallengeState.currentIndex >= overrideAllWordChallengeState.words.length
                        ? overrideAllChallengeText
                        : completedText;
                    if (overrideAllWordChallengeState.currentIndex < overrideAllWordChallengeState.words.length) {
                        renderOverrideAllWordChallengeState();
                        overrideAllChallengeWordInput.focus();
                        return;
                    }
                } else {
                    const modalContent = overrideAllModal.querySelector('.modal-content');
                    modalContent.classList.remove('wiggle');
                    void modalContent.offsetWidth;
                    modalContent.classList.add('wiggle');
                    overrideAllCurrentWordEl.textContent = getCurrentChallengeWord(overrideAllWordChallengeState);
                    return;
                }
            }

            const typed = getOverrideAllTypedValue();
            const target = overrideAllChallengeText;

            let firstErrorIndex = -1;
            if (typed !== target) {
                for (let i = 0; i < Math.max(typed.length, target.length); i++) {
                    if (typed[i] !== target[i]) {
                        firstErrorIndex = i;
                        break;
                    }
                }
                if (firstErrorIndex === -1 && typed.length < target.length) {
                    firstErrorIndex = typed.length;
                }
            }

            if (typed === target) {
                // Success! Clear everything
                await performOverrideAll();
                overrideAllModal.classList.add('hidden');
                overrideAllChallengeText = '';
                overrideAllWordChallengeState = null;
                setOverrideAllWordChallengeMode(false);
                confirmOverrideAllBtn.disabled = false;
            } else {
                // Wrong - wiggle and highlight error
                const modalContent = overrideAllModal.querySelector('.modal-content');
                modalContent.classList.remove('wiggle');
                void modalContent.offsetWidth; // Trigger reflow
                modalContent.classList.add('wiggle');

                if (overrideAllWordChallengeState) {
                    overrideAllCurrentWordEl.textContent = getCurrentChallengeWord(overrideAllWordChallengeState);
                } else {
                    renderOverrideAllChallengeText(firstErrorIndex);
                }
            }
        });
    }

}

// macOS in-app uninstall. The Uninstall button lives in Settings below
// Advanced options (not inside the collapsible). Hidden on Windows
// (`.macos-only` + `body.mac` gate) because Windows uses
// Settings → Apps → Uninstall, fully wired up by NSIS_HOOK_PREUNINSTALL.
//
// The button is *disabled* (not hidden) when any block / schedule is
// currently active, with a hint paragraph below nudging the user
// toward the Override-All challenge above. Rationale: uninstalling
// mid-block would leave the user with an unenforceable promise
// (no app = no enforcer), so we want the user to deliberately stop
// blocking first via the existing override path.

function firefoxHasReddFocusExtension(firefox) {
    const profiles = firefox?.profiles;
    if (!Array.isArray(profiles) || profiles.length === 0) return false;
    return profiles.some((p) => p.installed);
}

function applyUninstallConfirmModalStaticCopy() {
    syncUninstallDeleteDataCopy();

    const finderText = document.getElementById('uninstall-finder-warning-text');
    if (finderText) finderText.innerHTML = tSettings('uninstallFinderWarningHtml');

    const logo = document.getElementById('uninstall-firefox-callout-logo');
    if (logo) {
        logo.src = logoReddFocusUrl;
        logo.alt = '';
    }

    const titleText = document.getElementById('uninstall-firefox-callout-title-text');
    if (titleText) titleText.textContent = tSettings('uninstallFirefoxCalloutTitle');

    const badge = document.getElementById('uninstall-firefox-callout-badge');
    if (badge) badge.textContent = tSettings('uninstallExtFirefoxBadge');

    const detail = document.getElementById('uninstall-firefox-callout-detail');
    if (detail) {
        detail.innerHTML = tSettings('uninstallFirefoxCalloutDetailHtml')
            .replace('{URL_CHIP}', extensionsUrlChipHtml('firefox'));
        attachCopyChipHandlers(detail);
    }
}

function syncUninstallConfirmModal(browsers) {
    applyUninstallConfirmModalStaticCopy();
    const callout = document.getElementById('uninstall-firefox-callout');
    if (!callout) return;
    const showFirefox = !!(browsers && firefoxHasReddFocusExtension(browsers.firefox));
    callout.classList.toggle('hidden', !showFirefox);
}

async function fetchInstalledBrowsersForUninstall() {
    try {
        return await invoke('scan_browser_profiles');
    } catch (e) {
        if (lastOnboardingState?.browsers) {
            console.warn('uninstall: scan_browser_profiles failed, using cached browser state', e);
            return lastOnboardingState.browsers;
        }
        throw e;
    }
}

let uninstallConfirmResolver = null;

function syncUninstallDeleteDataCopy() {
    const checkbox = document.getElementById('uninstall-delete-data-checkbox');
    const lead = document.getElementById('uninstall-confirm-lead');
    if (!lead) return;
    const deleteData = checkbox?.checked === true;
    lead.innerHTML = tSettings(deleteData ? 'uninstallConfirmLeadDeleteHtml' : 'uninstallConfirmLeadHtml');
}

async function showUninstallConfirmModal() {
    const modal = document.getElementById('uninstall-confirm-modal');
    if (!modal) return null;

    const checkbox = document.getElementById('uninstall-delete-data-checkbox');
    if (checkbox) checkbox.checked = false;
    syncUninstallDeleteDataCopy();

    try {
        const browsers = await fetchInstalledBrowsersForUninstall();
        syncUninstallConfirmModal(browsers);
    } catch (e) {
        console.warn('uninstall: browser scan failed — hiding Firefox callout', e);
        syncUninstallConfirmModal(null);
    }

    return new Promise((resolve) => {
        uninstallConfirmResolver = resolve;
        modal.classList.remove('hidden');
    });
}

function closeUninstallConfirmModal(result) {
    const modal = document.getElementById('uninstall-confirm-modal');
    const checkbox = document.getElementById('uninstall-delete-data-checkbox');
    modal?.classList.add('hidden');
    if (uninstallConfirmResolver) {
        uninstallConfirmResolver(
            result ? { deleteUserData: checkbox?.checked === true } : null
        );
        uninstallConfirmResolver = null;
    }
}

function setupInAppUninstall() {
    const btn = document.getElementById('uninstall-app-btn');
    if (!btn) return;

    const modal = document.getElementById('uninstall-confirm-modal');
    document.getElementById('cancel-uninstall-confirm-btn')
        ?.addEventListener('click', () => closeUninstallConfirmModal(false));
    document.getElementById('confirm-uninstall-confirm-btn')
        ?.addEventListener('click', () => closeUninstallConfirmModal(true));
    document.getElementById('uninstall-delete-data-checkbox')
        ?.addEventListener('change', syncUninstallDeleteDataCopy);
    modal?.addEventListener('click', (e) => {
        if (e.target === modal) closeUninstallConfirmModal(false);
    });

    refreshUninstallButtonState();
    updateOverrideAllButtonVisibility();

    btn.addEventListener('click', async () => {
        // Re-check at click time so a schedule that fired between
        // settings-open and click can still gate us out cleanly.
        if (hasAnyBlockingStateToClear()) {
            refreshUninstallButtonState();
            return;
        }

        let confirmResult = null;
        try {
            confirmResult = await showUninstallConfirmModal();
        } catch (e) {
            console.error('uninstall: confirm dialog failed', e);
            return;
        }
        if (!confirmResult) return;

        // Close settings so the user sees a clean window before the
        // process exits and the bundle disappears.
        document.getElementById('settings-modal')?.classList.add('hidden');
        setLanguagePickerOpen(false);

        try {
            await tauriAPI.uninstallSelfMacos(confirmResult.deleteUserData);
            // Backend exits ~200ms later. The window typically
            // disappears before this promise resolves; nothing else
            // to do on success.
        } catch (e) {
            console.error('uninstall: backend command failed', e);
            try {
                await message(`${tSettings('uninstallFailed')}\n\n${e}`, {
                    title: tSettings('uninstallFailedTitle'),
                    kind: 'error',
                });
            } catch (_) { /* swallow — best-effort error surface */ }
        }
    });
}

// Refresh Uninstall / Open Settings buttons when blocks are active (same gate as macOS).
function refreshUninstallButtonState() {
    const blocking = hasAnyBlockingStateToClear();
    const disabledHint = tSettings('uninstallDisabledHint');

    for (const { btnId, hintId } of [
        { btnId: 'uninstall-app-btn', hintId: 'uninstall-app-hint' },
        { btnId: 'windows-uninstall-open-settings-btn', hintId: 'windows-uninstall-app-hint' },
    ]) {
        const btn = document.getElementById(btnId);
        const hint = document.getElementById(hintId);
        if (!btn) continue;

        if (blocking) {
            btn.disabled = true;
            btn.setAttribute('aria-disabled', 'true');
            if (hint) {
                hint.textContent = disabledHint;
                hint.classList.remove('hidden');
            }
        } else {
            btn.disabled = false;
            btn.removeAttribute('aria-disabled');
            if (hint) {
                hint.textContent = '';
                hint.classList.add('hidden');
            }
        }
    }
}

function setupWindowsUninstallGuidance() {
    if (isIOS) return;
    const btn = document.getElementById('windows-uninstall-open-settings-btn');
    if (!btn) return;

    refreshUninstallButtonState();

    btn.addEventListener('click', async () => {
        if (hasAnyBlockingStateToClear()) {
            refreshUninstallButtonState();
            return;
        }

        try {
            await openUrl(WINDOWS_APPS_SETTINGS_URI);
        } catch (e) {
            console.error('windows uninstall: open Settings failed', e);
            try {
                await message(`${tSettings('windowsUninstallOpenFailed')}\n\n${e}`, {
                    title: tSettings('windowsUninstallOpenFailedTitle'),
                    kind: 'error',
                });
            } catch (_) { /* dialog dismissed */ }
        }
    });
}


// Find the hardest challenge among all block/schedule state that could still resume later.
function findHardestChallenge() {
    const now = Date.now();
    const nowDate = new Date(now);
    let hardestDifficulty = null;

    // Check one-off blocks that still have remaining time.
    for (const block of appData.activeBlocks) {
        if (isOneOffBlockStillActive(block, now)) {
            const blocklist = appData.blocklists.find(bl => bl.id === block.blocklistId);
            if (blocklist?.overrideDifficulty) {
                hardestDifficulty = hardestDifficulty
                    ? compareDifficulties(hardestDifficulty, blocklist.overrideDifficulty)
                    : blocklist.overrideDifficulty;
            }
        }
    }

    // Check schedules that can still become active later.
    for (const schedule of appData.schedules || []) {
        if (!schedule.segments) continue;
        if (!scheduleCanStillBecomeActive(schedule, nowDate)) continue;

        const blocklist = appData.blocklists.find(bl => bl.id === schedule.blocklistId);
        if (blocklist?.overrideDifficulty) {
            hardestDifficulty = hardestDifficulty
                ? compareDifficulties(hardestDifficulty, blocklist.overrideDifficulty)
                : blocklist.overrideDifficulty;
        }
    }

    if (!hardestDifficulty) return { type: 'random-words', count: 50 };

    // Resolve effective count for maxDifficulty (handles single-block case
    // where compareDifficulties was never called)
    if (hardestDifficulty.maxDifficulty === true && hardestDifficulty.count === undefined) {
        const effectiveCount = getMaxOverrideCharsForType(hardestDifficulty.type);
        return { ...hardestDifficulty, count: effectiveCount };
    }
    return hardestDifficulty;
}

// Compare two difficulties and return the harder one
function compareDifficulties(a, b) {
    if (!a) return b;
    if (!b) return a;

    const getTypeRank = (difficulty) => {
        if (difficulty.type === 'custom') return 3;
        if (difficulty.type === 'gibberish') return 2;
        if (difficulty.type === 'random-words') return 1;
        return 0;
    };

    const aCount = getDifficultyTypingCharCount(a);
    const bCount = getDifficultyTypingCharCount(b);

    let winner;
    if (bCount > aCount) winner = b;
    else if (aCount > bCount) winner = a;
    else {
        // Same character count: custom > gibberish > random-words
        const aRank = getTypeRank(a);
        const bRank = getTypeRank(b);
        if (bRank > aRank) winner = b;
        else if (aRank > bRank) winner = a;
        else winner = a; // Equal, return a
    }

    // Resolve stored count for generation when maxDifficulty (keep word counts on iOS)
    if (winner.maxDifficulty === true) {
        const genCount = getMaxOverrideCharsForType(winner.type);
        if (winner.count !== genCount) {
            return { ...winner, count: genCount };
        }
    }
    return winner;
}

// Perform the actual override-all operation
async function performOverrideAll() {
    try {
        // Clear all active blocks
        appData.activeBlocks = [];

        // Clear all schedules
        appData.schedules = [];

        // Save the data
        await saveData();

        // Full cleanup on the helper side
        if (isIOS) {
            await tauriAPI.screentimeClearBlock();
        } else {
            const status = await refreshDesktopHelperStatus();
            if (status.helperReady) {
                // Atomically set everything to empty — helper will know nothing should be blocked
                try { await tauriAPI.setBlocksViaHelper([]); } catch (e) { console.warn('Failed to clear blocks:', e); }
                try { await tauriAPI.setSchedulesViaHelper([]); } catch (e) { console.warn('Failed to clear schedules:', e); }
                try { await tauriAPI.setBlockedAppsViaHelper([], [], [], false, false); } catch (e) { console.warn('Failed to clear apps:', e); }
            }
            // Always clean the hosts file as a safety net, even if the helper is stopped or stale.
            try { await tauriAPI.cleanHostsFile(); } catch (e) { console.warn('Failed to clean hosts file:', e); }
        }

        // Update blocked apps (will stop watcher if no apps to block)
        await updateBlockedApps();

        // Re-render the UI
        render();

        // Reset the blocklist selection UI
        const blocklistSelect = document.getElementById('blocklist-select');
        if (blocklistSelect) {
            handleBlocklistSelect({ target: blocklistSelect });
        }

        console.log('Override-all completed — all blocks, schedules, apps, and hosts entries cleared');
    } catch (err) {
        console.error('Error during override all:', err);
    }
}

